370: void Runtime::apply_events_at_boundary() {
371:     const auto range = pending_.equal_range(tick_);
372:     if (range.first == range.second) return;
373:     std::vector<PendingEvent> events;
374:     for (auto it = range.first; it != range.second; ++it) events.push_back(it->second);
375:     std::sort(events.begin(), events.end(), [](const PendingEvent& a, const PendingEvent& b) {
376:         return a.sequence < b.sequence;
377:     });
378:     std::map<std::size_t, std::size_t> target_counts;
379:     for (const auto& event : events) {
380:         for (const auto& write : event.writes) ++target_counts[index(write.coordinate)];
381:     }
382:     for (const auto& event : events) {
383:         EventStatus status = EventStatus::Applied;
384:         std::string reason;
385:         for (const auto& write : event.writes) {
386:             const auto idx = index(write.coordinate);
387:             if (target_counts[idx] > 1) {
388:                 status = EventStatus::RejectedConflict;
389:                 reason = "simultaneous events target the same register";
390:                 break;
391:             }
392:             if (raw_a_[idx] != 0) {
393:                 status = EventStatus::RejectedOccupied;
394:                 reason = "target register is not RAW-empty at application boundary";
395:                 break;
396:             }
397:         }
398:         auto& receipt = receipts_.at(event.id);
399:         receipt.status = status;
400:         receipt.reason = reason;
401:         if (status == EventStatus::Applied) {
402:             for (const auto& write : event.writes) {
403:                 raw_a_[index(write.coordinate)] = write.raw;
404:                 // Intentionally preserve the existing full clock word.
405:             }
406:             receipt.effective_tick = tick_;
407:         }
408:     }
409:     pending_.erase(range.first, range.second);

