189:     // v26-SYM1: reducer simetrico para TODAS las fuentes direccionales que apuntan al destino.
190:     // - 0 fuentes: conserva el comportamiento nulo.
191:     // - 1 fuente: conserva EXACTAMENTE el raw de v25.
192:     // - >1 fuentes: suma s_reg con la misma cota P_KERNEL-1 ya usada por DEMUX,
193:     //   y compone la direccion mediante signo de la suma vectorial.
194:     // La reduccion es conmutativa y no depende del indice de MOORE_DXYZ.
195:     int count = 0;
196:     uint64_t only_source = 0;
197:     uint32_t sum_sreg = 0;
198:     int sum_dx = 0, sum_dy = 0, sum_dz = 0;
199: 
