201:         int nx = wrap(x + MOORE_DXYZ[k][0], N);
202:         int ny = wrap(y + MOORE_DXYZ[k][1], N);
203:         int nz = wrap(z + MOORE_DXYZ[k][2], N);
204:         size_t nidx = idx3d(nx, ny, nz, N);
205:         uint64_t nv = gA[nidx];
206:         int ndx = get_dir_x(nv), ndy = get_dir_y(nv), ndz = get_dir_z(nv);
207:         if (ndx == 0 && ndy == 0 && ndz == 0) continue;
208:         if (wrap(nx + ndx, N) == x && wrap(ny + ndy, N) == y && wrap(nz + ndz, N) == z) {
209:             ++count;
210:             only_source = nv;
211:             sum_sreg += static_cast<uint32_t>(get_s_reg(nv));
212:             sum_dx += ndx;
213:             sum_dy += ndy;
